pou.interface:
{implicit on}
FUNCTION __HelpConvertDate : BOOL
VAR_INPUT
	in : UDINT;
	ppstr : POINTER TO POINTER TO BYTE;
END_VAR
VAR
	nYear : UDINT;
	nMonth : UDINT;
	nDay : UDINT;
	DayOfMonthTable : ARRAY [0..11] OF BYTE := [31,28,31,30,31,30,31,31,30,31,30,31];
	pstr : POINTER TO BYTE := ppstr^;
END_VAR
{implicit off}

pou.body:

	{implicit on}
	{nobp}
	{noflow}
	in := in / (UDINT#24 * UDINT#3600);

	{IF COMPILERVERSION(>=, '3.2.1.20')}
	IF (in >= 47541) THEN
		in := in + 1; // add a "virtual" 29 of February 2100 and calculate as if there was one
	END_IF
  {END_IF}		

	nYear := 4 * (in / UDINT#1461) + UDINT#1970;
	in := in MOD 1461;
	IF (in < UDINT#2 * UDINT#365) THEN
		nYear := nYear + (in / 365);
		in := in MOD 365;
		DayOfMonthTable[1] := 28;
	ELSIF (in < UDINT#2 * UDINT#365 + UDINT#366) THEN
		DayOfMonthTable[1] := 29;
		nYear := nYear + 2;
		in := in - UDINT#2 * UDINT#365;
	ELSE
		nYear := nYear + 3;
		DayOfMonthTable[1] := 28;
		{IF COMPILERVERSION(>=, '3.2.1.20')}
		in := in - (UDINT#2 * UDINT#365 + UDINT#366);
		{ELSE}
		in := in - UDINT#2 * UDINT#365 + UDINT#366;
		{END_IF}
	END_IF

	WHILE (in >= DayOfMonthTable[nMonth]) DO
		in := in - DayOfMonthTable[nMonth];
		nMonth := nMonth + 1;
	END_WHILE

	nMonth := nMonth + 1;
	nDay := in + 1;  (* nYear, nMonth, nDay are complete *)
	__HelpConvert(nYear, ADR(pstr),4);
	pstr[0] := BYTE#16#2d; (*'-'*)
	pstr := pstr + 1;
	__HelpConvert(nMonth,ADR(pstr), 2);
	pstr[0] := BYTE#16#2d; (*'-'*)
	pstr := pstr + 1;
	__HelpConvert(nDay,ADR(pstr), 2);
	ppstr^ := pstr;
	{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpConvertString : UDINT
VAR_INPUT
	pstr : POINTER TO BYTE;
	nWidth : UDINT;
END_VAR
VAR
	i : UDINT;
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}    
		{IF COMPILERVERSION(>=, '3.5.2.0')}
		  IF (nWidth = 0) THEN
        __HelpConvertString := 0;
        RETURN;
      END_IF
		{END_IF}                              
		FOR (i := 0) TO nWidth - 1 DO
			__HelpConvertString := __HelpConvertString * 10 + pstr[0] - 16#30 (*'0'*);
			pstr := pstr+1;
		END_FOR
		{implicit off}

pou.interface:
{implicit on}
FUNCTION __LEFT : STRING(255)
VAR_INPUT
	STR:STRING(255);
	SIZE:INT;
END_VAR
VAR
	p1, pResult : POINTER TO BYTE;
	index : INT;
END_VAR		
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
p1 := ADR (STR);
pResult := ADR(__LEFT);

FOR index := 0 TO SIZE - 1 DO
	pResult^ := p1^;
	IF (pResult^ = 0) THEN
		EXIT;
	END_IF
	pResult := pResult + 1;
	p1 := p1 + 1;
END_FOR
pResult^:= 0;
{implicit off}

pou.interface:
{implicit on}
FUNCTION __SkipWhiteSpace : BOOL
VAR_INPUT
	ppstr : POINTER TO POINTER TO BYTE;
END_VAR
VAR
	pstr : POINTER TO BYTE := ppstr^;
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
WHILE (pstr[0] = 16#20 OR pstr[0] = 16#09) DO
	pstr := pstr + 1;
END_WHILE
ppstr^ := pstr;	
{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpConvert : BOOL
VAR_INPUT
	in : UDINT;
	ppstr : POINTER TO POINTER TO BYTE;
	nWidth : DINT;
END_VAR
VAR
	ulDiv : UDINT := 1000000000;
	bFirst : BOOL;
	pstr : POINTER TO BYTE := ppstr^;
	nDigits : DINT := 10;
	ulDig : UDINT;
	count: UDINT;
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
WHILE (ulDiv > 0) DO
	ulDig := in / ulDiv;
	IF ((NOT bFirst AND ulDig <> 0) OR (nDigits <= nWidth)) THEN
		bFirst := TRUE;
	END_IF
	IF (bFirst) THEN
		pstr[0] := UDINT_TO_BYTE(ulDig + 16#30); (*'0'*)
		pstr := pstr + 1; 
		in := in MOD ulDiv;
		count := count + 1;
	END_IF
	ulDiv := ulDiv / 10;
	nDigits := nDigits-1;
END_WHILE

pstr[0] := 0; (*'\0'*)
ppstr^ := pstr;

{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpConvertTime : BOOL
VAR_INPUT
	in : UDINT;
	ppstr : POINTER TO POINTER TO BYTE;
END_VAR
VAR
	dwHour : UDINT;
	dwMinute : UDINT;
	dwSecond : UDINT;
	dwMilliSecond : UDINT;
	pstr : POINTER TO BYTE := ppstr^;
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}
		dwHour := in / 3600000;
		in := in MOD 3600000;
		dwMinute := in / 60000;
		in := in MOD 60000;
		dwSecond := in / 1000; 
		dwMilliSecond := in MOD 1000;

		__HelpConvert(dwHour,ADR(pstr), 2);
		pstr[0] := 16#3A; (*':'*)
		pstr := pstr + 1;
		__HelpConvert(dwMinute,ADR(pstr), 2);
		pstr[0] := 16#3A; (*':'*)
		pstr := pstr + 1;
		__HelpConvert(dwSecond,ADR(pstr), 2);

		IF (dwMilliSecond <> 0) THEN
			pstr[0] := 16#2E; (*'.'*)
			pstr := pstr + 1;
			__HelpConvert(dwMilliSecond, ADR(pstr), 3);
		END_IF

    {IF COMPILERVERSION(>=, '3.5.16.0')}    
        IF (dwMilliSecond = 0) THEN
          ppstr^ := pstr;
        END_IF
    {END_IF}

		{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpConvertTimeUnits : UDINT
VAR_INPUT
	ppstr : POINTER TO POINTER TO BYTE;	
END_VAR
VAR
	pstr : POINTER TO BYTE := ppstr^;
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}
    {IF COMPILERVERSION(>=, '3.5.13.0')}		    
		    CASE (pstr[0]) OF
        16#64: (*'d'*)
          __HelpConvertTimeUnits := 86400000;      
		    16#68: (*'h'*)
			    __HelpConvertTimeUnits := 3600000;
		    16#73: (*'s'*)
			    __HelpConvertTimeUnits  := 1000;
		    16#6D: (*'m'*)
			    IF (pstr[1] = 16#73) THEN
				    pstr := pstr+1;
				    __HelpConvertTimeUnits  := 1;
			    ELSE
				    __HelpConvertTimeUnits  := 60000;
			    END_IF
		    ELSE 
			    __HelpConvertTimeUnits  :=  0;
			    {IF COMPILERVERSION(>=, '3.5.2.0')}
            IF (pstr[0] = 16#00) THEN
			        RETURN;
            END_IF     
			    {END_IF}
		    END_CASE    
    {ELSE}
		    CASE (pstr[0]) OF
		    16#68: (*'h'*)
			    __HelpConvertTimeUnits := 3600000;
		    16#73: (*'s'*)
			    __HelpConvertTimeUnits  := 1000;
		    16#6D: (*'m'*)
			    IF (pstr[1] = 16#73) THEN
				    pstr := pstr+1;
				    __HelpConvertTimeUnits  := 1;
			    ELSE
				    __HelpConvertTimeUnits  := 60000;
			    END_IF
		    ELSE 
			    __HelpConvertTimeUnits  :=  0;
			    {IF COMPILERVERSION(>=, '3.5.2.0')}
            IF (pstr[0] = 16#00) THEN
			        RETURN;
            END_IF     
			    {END_IF}
		    END_CASE
    {END_IF}
		pstr := pstr+1;
		ppstr^ := pstr;
		{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpConvertFromTime : UDINT
VAR_INPUT
	ppstr : POINTER TO POINTER TO BYTE;
END_VAR
VAR
	pstr : POINTER TO BYTE := ppstr^;
	nHour : UDINT;
	nMinutes : UDINT;
	nSeconds : UDINT;
	nMilliseconds : UDINT;
	pstrHelpHour : POINTER TO BYTE;
	pstrHelpMinute : POINTER TO BYTE;
	pstrHelpSecond : POINTER TO BYTE;
	pstrHelpMilliSecond : POINTER TO BYTE;
	i : UDINT;
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
pstrHelpHour := pstr;
WHILE(pstrHelpHour[0] <> 16#3A(*':'*)) AND (pstrHelpHour[0] <> 0) DO
	pstrHelpHour := pstrHelpHour + 1;
END_WHILE
i := pstrHelpHour - pstr;
IF (i = 1 OR i = 2) THEN
	nHour := __HelpConvertString(pstr,i);
ELSE
	RETURN;
END_IF

IF (pstrHelpHour[0] = 0) THEN
	__HelpConvertFromTime := ((nHour * UDINT#3600) * UDINT#1000);
	RETURN;
END_IF 

pstrHelpHour := pstrHelpHour + 1;
pstrHelpMinute := pstrHelpHour;

WHILE(pstrHelpMinute[0] <> 16#3A(*':'*)) AND (pstrHelpMinute[0] <> 0) DO
	pstrHelpMinute := pstrHelpMinute + 1;
END_WHILE
i := pstrHelpMinute - pstrHelpHour;
IF (i = 1 OR i = 2) THEN
	nMinutes := __HelpConvertString(pstrHelpHour,i);
ELSE
	RETURN;
END_IF

IF (pstrHelpMinute[0] = 0) THEN
	__HelpConvertFromTime := ((nHour * UDINT#3600 + nMinutes * UDINT#60) * UDINT#1000);
	RETURN;
END_IF 

pstrHelpMinute := pstrHelpMinute + 1;
pstrHelpSecond := pstrHelpMinute;

WHILE(pstrHelpSecond[0] <> 16#2E(*'.'*)) AND (pstrHelpSecond[0] <> 0)DO
	pstrHelpSecond := pstrHelpSecond + 1;
END_WHILE
i := pstrHelpSecond - pstrHelpMinute;

IF ((i = 1 OR i = 2) AND pstrHelpSecond[0] = 0 ) THEN
	nSeconds := __HelpConvertString(pstrHelpMinute,i);
	ppstr^ := pstrHelpSecond;
	__HelpConvertFromTime := ((nHour * UDINT#3600 + nMinutes * UDINT#60 + nSeconds) * UDINT#1000); 
	RETURN;
ELSIF ((i = 1 OR i = 2) AND pstrHelpSecond[0] = 16#2E(*'.'*)) THEN
	nSeconds := __HelpConvertString(pstrHelpMinute,i);
	pstrHelpSecond := pstrHelpSecond+1;
	pstrHelpMilliSecond := pstrHelpSecond;
	WHILE(pstrHelpMilliSecond[0] <> 0) DO
		pstrHelpMilliSecond := pstrHelpMilliSecond+1;
	END_WHILE
	i := pstrHelpMilliSecond - pstrHelpSecond;
	IF (i = 1 OR i = 2 OR i = 3) THEN
		nMilliSeconds := REAL_TO_UDINT(__HelpConvertString(pstrHelpSecond,i) * EXPT(10,3 - i));
	ELSE
		RETURN;
	END_IF
	ppstr^ := pstrHelpMilliSecond;
	__HelpConvertFromTime := (((nHour * UDINT#3600 + nMinutes * UDINT#60 + nSeconds) * UDINT#1000) + nMilliSeconds);
ELSE
	__HelpConvertFromTime := ((nHour * UDINT#3600+ nMinutes * UDINT#60) * UDINT#1000); 
END_IF
{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpConvertStringBase : UDINT
VAR_INPUT
	pstr : POINTER TO BYTE;
	nBase : INT;
END_VAR
VAR
	nNext : INT;
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
WHILE(pstr[0] <> 0) DO
	IF (pstr[0] = 16#5f) THEN (*'_'*)
		pstr := pstr + 1;
	ELSE
		IF ((nBase = 2 AND pstr[0] >= 16#30 (*'0'*) AND pstr[0] <= 16#31 (*'1'*)) 
			OR (nBase = 8 AND pstr[0] >= 16#30 (*'0'*) AND pstr[0] <= 16#37 (*'7'*))
			OR (nBase = 10 AND pstr[0] >= 16#30 (*'0'*) AND pstr[0] <= 16#39 (*'9'*))
			OR (nBase = 16 AND pstr[0] >= 16#30 (*'0'*) AND pstr[0] <= 16#39 (*'9'*)))
		THEN
			nNext := pstr[0] - 16#30;
		ELSIF (nBase = 16 AND pstr[0] >= 16#41 (*'A'*) AND pstr[0] <= 16#46 (*'F'*)) THEN
			nNext := pstr[0] - 16#41 + 10;
		ELSIF (nBase = 16 AND pstr[0] >= 16#61 (*'a'*) AND pstr[0] <= 16#66 (*'f'*)) THEN
			{IF COMPILERVERSION(>=, '3.4.0.0')}
				nNext := pstr[0] - 16#61 + 10;
			{ELSE}
				nNext := pstr[0] - 16#46 + 10;
			{END_IF}
		ELSE
			EXIT;
		END_IF
		__HelpConvertStringBase := DINT_TO_UDINT(UDINT_TO_DINT(__HelpConvertStringBase) * nBase + nNext);
		pstr := pstr + 1;
	END_IF
END_WHILE
{IF COMPILERVERSION(<, '3.5.0.0')}
	IF (pstr[0] <> 0 AND pstr[0] <> 16#2e(*'.'*)) THEN
		__HelpConvertStringBase := 0; 
	END_IF
{END_IF}
{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpConvertFromDate : UDINT
VAR_INPUT
	ppstr : POINTER TO POINTER TO BYTE;
END_VAR
VAR
	pstr : POINTER TO BYTE := ppstr^;
	nYear : UDINT;
	nMonth : UDINT;
	nDay : UDINT;
	nDiffYear : UDINT;
	nDiffYearDiv : UDINT;
	nDiffYearMod : UDINT;
	nCount : UDINT;
	ulTime : UDINT;
	pstrHelpYear : POINTER TO BYTE := pstr;
	pstrHelpMonth : POINTER TO BYTE;
	pstrHelpDay : POINTER TO BYTE;
	i : DINT;
	DayOfMonthTable : ARRAY [0..11] OF BYTE := [31,28,31,30,31,30,31,31,30,31,30,31];
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}
    {IF COMPILERVERSION(>=, '3.5.14.0')}
		  WHILE(pstrHelpYear[0] <> BYTE#0 AND pstrHelpYear[0] <> BYTE#16#2d (*'-'*)) DO
			  pstrHelpYear := pstrHelpYear + 1;
		  END_WHILE      
    {ELSE}
		  WHILE(pstrHelpYear[0] <> BYTE#16#2d (*'-'*)) DO
			  pstrHelpYear := pstrHelpYear + 1;
		  END_WHILE      
    {END_IF}

		i := DWORD_TO_DINT(pstrHelpYear - pstr);

		IF (i = 4) THEN
			nYear := __HelpConvertString(pstr,4);
		ELSE
			RETURN;
		END_IF

    {IF COMPILERVERSION(>=, '3.5.20.0')}
		IF (pstrHelpYear[0] = BYTE#0) THEN
			RETURN;
		END_IF
	{END_IF}

		pstrHelpYear := pstrHelpYear + 1;
		pstrHelpMonth := pstrHelpYear;

	{IF COMPILERVERSION(>=, '3.5.20.0')}
		WHILE(pstrHelpMonth[0] <> BYTE#0 AND pstrHelpMonth[0] <> BYTE#16#2d (*'-'*)) DO
			pstrHelpMonth := pstrHelpMonth+1;
		END_WHILE
	{ELSE}
		WHILE(pstrHelpMonth[0] <> BYTE#16#2d (*'-'*)) DO
			pstrHelpMonth := pstrHelpMonth+1;
		END_WHILE
	{END_IF}		

		i := DWORD_TO_DINT(pstrHelpMonth - pstrHelpYear);
		IF (i = 1 OR i = 2) THEN
			nMonth := __HelpConvertString(pstrHelpYear,DINT_TO_UDINT(i));
		ELSE
			RETURN;
		END_IF

    {IF COMPILERVERSION(>=, '3.5.20.0')}
		IF (pstrHelpMonth[0] = BYTE#0) THEN
			RETURN;
		END_IF
	{END_IF}

		pstrHelpMonth := pstrHelpMonth+1;
		pstrHelpDay := pstrHelpMonth;
		WHILE(pstrHelpDay[0] <> 0 AND pstrHelpDay[0] <> BYTE#16#2d (*'-'*)) DO
			pstrHelpDay := pstrHelpDay + 1;
		END_WHILE

		i := DWORD_TO_DINT(pstrHelpDay - pstrHelpMonth);
		IF (i = 1 OR i = 2) THEN
			nDay := __HelpConvertString(pstrHelpMonth,DINT_TO_UDINT(i));
		ELSE 
			RETURN;
		END_IF

		ppstr^ := pstrHelpDay;

		nDiffYear := nYear - 1970;
		nDiffYearDiv := nDiffYear / 4;
		nDiffYearMod := nDiffYear MOD 4;

		CASE (nDiffYearMod) OF
			0,1:
				nCount := nDiffYearDiv;
			2:
				IF (nMonth < 3) THEN
					nCount := nDiffYearDiv;
				ELSE
					nCount := nDiffYearDiv + 1;
				END_IF
			3:
				nCount := nDiffYearDiv + 1;
		END_CASE

		{IF COMPILERVERSION(>=, '3.2.1.20')}
		IF (nYear > 2100 OR (nYear = 2100 AND nMonth >= 3)) THEN
			nCount := nCount - 1; // one day less because there is no 29.2.2100
		END_IF
		{END_IF}

		ulTime := (nDiffYear * UDINT#365 + nCount) * UDINT#24 * UDINT#3600;
		FOR i := 0 TO UDINT_TO_DINT(nMonth - 2) DO
			ulTime := ulTime + (DayOfMonthTable[i] * UDINT#24 * UDINT#3600);
		END_FOR
		ulTime := ulTime + ((nDay-1) * UDINT#24 * UDINT#3600);

		__HelpConvertFromDate := ulTime;
		{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpConvertTimeWithUnit : BOOL
VAR_INPUT
in : UDINT;
ppstr : POINTER TO POINTER TO BYTE;
END_VAR
VAR
{IF COMPILERVERSION(>=, '3.5.11.0')}
  dwDay: UDINT;
  dwHour: UDINT;
{END_IF}
dwMinute : UDINT;
dwSecond : UDINT;
dwMilliSecond : UDINT;
pstr : POINTER TO BYTE := ppstr^;
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}
		pstr[0] := 16#54; (*'T'*)
		pstr[1] := 16#23; (*'#'*)
		pstr := pstr + 2;

		IF (in = 0) THEN
			pstr[0] := 16#30; (*'0'*)
			pstr[1] := 16#6D; (*'m'*)
			pstr[2] := 16#73; (*'s'*)
			pstr[3] := 16#0;  (*'\0'*)
			pstr := pstr + 3;
		ELSE

      {IF COMPILERVERSION(>=, '3.5.11.0')}
	      dwDay := in / 86400000;
	      in := in MOD 86400000;
	      dwHour := in / 3600000;
	      in := in MOD 3600000; 
      {END_IF}

			dwMinute := in / 60000;
			in := in MOD 60000;
			dwSecond := in / 1000; 
			dwMilliSecond := in MOD 1000;

      {IF COMPILERVERSION(>=, '3.5.11.0')}
	      IF (dwDay <> 0) THEN
		      __HelpConvert(dwDay,ADR(pstr), 1);
		      pstr[0] := 16#64; (*'d'*)
		      pstr := pstr + 1;		
	      END_IF
	      IF (dwHour <> 0) THEN
		      __HelpConvert(dwHour,ADR(pstr), 1);
		      pstr[0] := 16#68; (*'h'*)
		      pstr := pstr + 1;		
	      END_IF      
      {END_IF}

			IF (dwMinute <> 0) THEN
				__HelpConvert(dwMinute,ADR(pstr), 1);
				pstr[0] := 16#6D; (*'m'*)
				pstr := pstr + 1;
			END_IF
			IF (dwSecond <> 0) THEN
				__HelpConvert(dwSecond,ADR(pstr), 1);
				pstr[0] := 16#73; (*'s'*)
				pstr := pstr + 1;
			END_IF
			IF (dwMilliSecond <> 0) THEN
				__HelpConvert(dwMilliSecond, ADR(pstr), 1);
				pstr[0] := 16#6D; (*'m'*)
				pstr[1] := 16#73; (*'s'*)
				pstr := pstr + 2;
			END_IF
			pstr[0] := 0; (*'\0'*)
		END_IF

		ppstr^ := pstr;	
		{implicit off}

pou.interface:
{implicit on}
FUNCTION any32__to__string : STRING(255)
VAR_INPUT
	in: DWORD;
	dwType: DWORD;
END_VAR
VAR
	diExponent : DINT;
	dwMant : UDINT;
	diExp10 : DINT;
	pstr: POINTER TO BYTE;
	diAfterKomma: DINT;
	udPow : UDINT;
	dwTOD : DWORD;
	dwDate: DWORD;
	pszHelp: STRING(INT#1);
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
pstr := ADR(any32__to__string);
IF (dwType = __TypeClass.TYPE_DATE) THEN
	pstr[0] := 16#44; (*'D'*)
	pstr[1] := 16#23; (*'#'*)
	pstr := pstr + 2; 
	__HelpConvertDate(in, ADR(pstr));
	RETURN;
END_IF
IF (dwType = __TypeClass.TYPE_TIMEOFDAY) THEN
	pstr[0] := 16#54; (*'T'*)
	pstr[1] := 16#4f; (*'O'*)
	pstr[2] := 16#44; (*'D'*)
	pstr[3] := 16#23; (*'#'*)
	pstr := pstr + 4;
	__HelpConvertTime(in, ADR(pstr));
	RETURN;
END_IF
IF (dwType = __TypeClass.TYPE_DATEANDTIME) THEN
	dwTOD := in MOD (DWORD#24 * DWORD#3600);
	dwDate := in - dwTOD;
	pstr[0] := 16#44; (*'D'*)
	pstr[1] := 16#54; (*'T'*)
	pstr[2] := 16#23; (*'#'*)
	pstr := pstr + 3;
	__HelpConvertDate(dwDate, ADR(pstr));
	pstr[0] := BYTE#16#2d; (*'-'*)
	pstr := pstr + 1;
	__HelpConvertTime(dwTOD * 1000, ADR(pstr));
	RETURN;
END_IF
IF (dwType = __TypeClass.TYPE_TIME) THEN
	__HelpConvertTimeWithUnit(in,ADR(pstr));
	RETURN;
END_IF
IF (dwType = __TypeClass.TYPE_REAL) THEN  
	IF (in = 0) THEN
		any32__to__string := '0';
		RETURN;
	END_IF
	(* between 0 and 255, 127 => exponent is zero *)
	diExponent := DWORD_TO_DINT(SHR(in AND DWORD#16#7FFFFFFF, 23));
	dwMant := ((in AND DWORD#16#7FFFFF) OR DWORD#16#800000);
	(* Consider the mantissa as a integer *)
	diExponent := diExponent-23;
	(* Convert base 2 exponent to base 10 exponent for positive exponents *)
	WHILE (diExponent > 127) DO
		dwMant := SHL(dwMant, 1);
		diExponent := diExponent - 1;
		IF (dwMant > 16#7FFFFFFF) THEN
			dwMant := dwMant / 10;
			diExp10 := diExp10 + 1;
		END_IF
	END_WHILE
	(* Convert base 2 exponent to base 10 exponent for negative exponents *)
	WHILE (diExponent < 127) DO
		WHILE (dwMant < DWORD#16#FFFFFFFF / DWORD#10) DO
			dwMant := dwMant*10;
			diExp10 := diExp10-1;
		END_WHILE
		dwMant  := SHR(dwMant, 1);
		diExponent := diExponent+1;
	END_WHILE
	(* Normalize to standard accuracy *)
	WHILE (dwMant >= 1000000) DO
		dwMant := (dwMant + 5) / 10;
		diExp10 := diExp10+1;
	END_WHILE
	(* Emit sign *)
	IF (DWORD_TO_DINT(in) < 0) THEN
		pstr^ := BYTE#16#2d; (*'-'*)
		pstr := pstr + 1;
	END_IF
	IF (diExp10 <= 0 AND diExp10 >= -5) THEN
	(* No exponent required *)
		udPow := 1;
		diAfterKomma := 0;
		WHILE (diExp10 <> -diAfterKomma) DO
			udPow := udPow * 10;
			diAfterKomma := diAfterKomma+1;
		END_WHILE
	ELSE
		udPow := 100000;
		diAfterKomma := 5;
	END_IF
	__HelpConvert(dwMant / udPow, ADR(pstr), 6 - diAfterKomma);
	pstr^ := BYTE#16#2e; (*'.';*)
	pstr := pstr + 1;
	__HelpConvert(dwMant MOD udPow, ADR(pstr), diAfterKomma);
	diExp10 := diExp10 + diAfterKomma;
	IF (diExp10 <> 0) THEN
		pstr^ := 16#65; (*e*)
		pstr := pstr + 1;
		IF (diExp10 < 0) THEN
			pstr^ := BYTE#16#2d; (*'-'*)
			pstr := pstr + 1;
			__HelpConvert(DINT_TO_DWORD(-diExp10), ADR(pstr), 2);
		ELSE
			__HelpConvert(DINT_TO_DWORD(diExp10), ADR(pstr), 2);
		END_IF
	END_IF
	RETURN;
END_IF
IF (dwType = __TypeClass.TYPE_BOOL) THEN  
	IF (in <> 0) THEN
		any32__to__string := 'TRUE';
	ELSE
		any32__to__string := 'FALSE';
	END_IF
	RETURN;
END_IF

(*Numbers*)
IF ((dwType = __TypeClass.TYPE_SINT OR dwType = __TypeClass.TYPE_INT OR dwType = __TypeClass.TYPE_DINT) 
	AND in > DWORD#16#7FFFFFFF) THEN
	(* Sign of result *)
	in := DINT_TO_DWORD(-(DWORD_TO_DINT(in)));
	pstr[0] := BYTE#16#2d; (*'-'*)
	pstr[1] := 0; (*'\0'*)
	pstr := pstr + 1;
ELSE
	pstr[0] := 0; (*'\0'*)
END_IF
IF (dwType = __TypeClass.TYPE_BYTE OR dwType = __TypeClass.TYPE_WORD OR dwType = __TypeClass.TYPE_DWORD
	OR dwType = __TypeClass.TYPE_USINT OR dwType = __TypeClass.TYPE_UINT OR dwType = __TypeClass.TYPE_UDINT) THEN
		pstr[0] := 0; (*'\0'*)
END_IF
__HelpConvert(in, ADR(pstr),1);
{implicit off}

pou.interface:
{implicit on}
FUNCTION string__to__any32 : DWORD
VAR_INPUT
	in: STRING(255);
	dwType: DWORD;
END_VAR
VAR
	pstr : POINTER TO STRING := ADR(in);
	ulHelpDt: UDINT;
	strHelp : STRING(4);
	pstrHelp : POINTER TO BYTE; 
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
__SkipWhiteSpace(ADR(pstr));

IF (dwType = __TypeClass.TYPE_DATE) THEN
	IF (__LEFT(pstr^, 2) <> 'd#') AND (__LEFT(pstr^, 2) <> 'D#')
		AND (__LEFT(pstr^, 5) <> 'DATE#') AND (__LEFT(pstr^, 5) <> 'date#') THEN
			string__to__any32 := 0;
			RETURN;
	END_IF
	WHILE (pstr^[0] <> 16#23) (*'#'*) DO
		pstr := pstr+1;
	END_WHILE
	pstr := pstr+1;
	string__to__any32 := __HelpConvertFromDate(ADR(pstr)); 
	RETURN;
END_IF
IF (dwType = __TypeClass.TYPE_TIMEOFDAY) THEN
	IF (__LEFT(pstr^, 4) <> 'tod#') AND (__LEFT(pstr^, 4) <> 'TOD#') 
		AND (__LEFT(pstr^, 12) <> 'TIME_OF_DAY#')
		AND (__LEFT(pstr^, 12) <> 'time_of_day#') THEN
		string__to__any32 := 0;
		RETURN;
	END_IF
	WHILE (pstr^[0] <> 16#23) (*'#'*) DO
		pstr := pstr+1;
	END_WHILE
	pstr := pstr+1;
	string__to__any32 := __HelpConvertFromTime(ADR(pstr));
	RETURN; 
END_IF
IF (dwType = __TypeClass.TYPE_DATEANDTIME) THEN
	IF (__LEFT(pstr^, 3) <> 'dt#') AND (__LEFT(pstr^, 3) <> 'DT#') 
		AND (__LEFT(pstr^, 14) <> 'DATE_AND_TIME#')
		AND (__LEFT(pstr^, 14) <> 'date_and_time#') THEN
		string__to__any32 := 0;
		RETURN;
	END_IF
	WHILE (pstr^[0] <> 16#23) (*'#'*) DO
		pstr := pstr+1;
	END_WHILE
	pstr := pstr+1;
	ulHelpDt := __HelpConvertFromDate(ADR(pstr));
	pstr := pstr+1;
	string__to__any32 := ulHelpDt + __HelpConvertFromTime(ADR(pstr)) / 1000;
	RETURN;
END_IF
(* TODO : __TypeClass.TYPE_REAL not necessary for FPU *)
IF (dwType = __TypeClass.TYPE_SINT OR dwType = __TypeClass.TYPE_INT OR dwType = __TypeClass.TYPE_DINT
			OR dwType = __TypeClass.TYPE_BYTE OR dwType = __TypeClass.TYPE_WORD OR dwType = __TypeClass.TYPE_DWORD
			OR dwType = __TypeClass.TYPE_USINT OR dwType = __TypeClass.TYPE_UINT OR dwType = __TypeClass.TYPE_UDINT)
THEN
	IF pstr^[0] = 0 (*'\0'*) THEN
		string__to__any32 := 0;
		RETURN;
	END_IF
	IF (__LEFT(pstr^, 3) = '16#') THEN
		string__to__any32 := __HelpConvertStringBase(pstr + 3,16);
		RETURN;
	ELSIF (__LEFT(pstr^, 2) = '2#')THEN
		string__to__any32 := __HelpConvertStringBase(pstr + 2,2);
		RETURN;
	ELSIF  (__LEFT(pstr^, 2) = '8#') THEN
		string__to__any32 := __HelpConvertStringBase(pstr + 2,8);
		RETURN;
	ELSE 
		IF (pstr^[0] = BYTE#16#2d (*'-'*) AND (dwType = __TypeClass.TYPE_SINT OR dwType = __TypeClass.TYPE_INT OR 
				dwType = __TypeClass.TYPE_DINT))
		THEN
			pstr := pstr+1;
			string__to__any32 := DINT_TO_UDINT(-UDINT_TO_DINT(__HelpConvertStringBase(pstr,10)));
			RETURN;
		ELSE
			IF (pstr^[0] = BYTE#16#2b (*'+'*)) THEN
				pstr := pstr+1;
			END_IF
			string__to__any32 := __HelpConvertStringBase(pstr,10);
			RETURN;
		END_IF
	END_IF
	string__to__any32 := 0;
	RETURN; 
END_IF

IF (dwType = __TypeClass.TYPE_BOOL) THEN
	IF (__LEFT(pstr^,4) = 'TRUE') OR (__LEFT(pstr^,4) = 'true') THEN
		string__to__any32 := 1;
	ELSE 
		string__to__any32 := 0;
	END_IF
	RETURN;
END_IF

IF (dwType = __TypeClass.TYPE_TIME) THEN
	IF (__LEFT(pstr^, 2) <> 't#') AND (__LEFT(pstr^, 2) <> 'T#') 
		AND (__LEFT(pstr^, 5) <> 'TIME#') AND (__LEFT(pstr^, 5) <> 'time#') THEN
			string__to__any32 := 67;
			RETURN;
	END_IF
	WHILE (pstr^[0] <> 16#23) (*'#'*) DO
		pstr := pstr+1;
	END_WHILE
	pstr := pstr+1;

	WHILE (pstr^[0] <> 0 (*'\0'*)) DO
		pstrHelp := ADR(strHelp);
		WHILE((pstr^[0] >= 16#30(*'0'*) AND pstr^[0] <= 16#39(*'9'*)) OR pstr^[0] = 16#5f (*'_'*)) DO
			IF (pstr^[0] = 16#5f (*'_'*)) THEN
				pstr := pstr + 1;
			ELSE
				pstrHelp[0] := pstr^[0];
				pstrHelp := pstrHelp+1;
				pstr := pstr+1;
			END_IF
		END_WHILE
		string__to__any32 := string__to__any32  + __HelpConvertString(ADR(strHelp),pstrHelp-ADR(strHelp)) * __HelpConvertTimeUnits(ADR(pstr));
	END_WHILE
	RETURN;
END_IF

{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpReal32Convert : BOOL
VAR_INPUT
in : REAL;
ppstr : POINTER TO POINTER TO BYTE;
pnBegin : POINTER TO DINT;
END_VAR
VAR
bFirst : BOOL := FALSE;
pstr : POINTER TO BYTE := ppstr^;
nDigits : DINT := 309;
nDig : UDINT;
i : DINT;
dBegin : REAL;
dDiv : REAL;
bNeg : BOOL;
nHelpBegin : DINT;
dDiff : REAL;
j: INT;
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}
		dBegin := LOG(in);
		bNeg := FALSE;
		IF (dBegin < 0) THEN
			nHelpBegin := TRUNC(dBegin);
			IF (DINT_TO_REAL(nHelpBegin) <> dBegin) THEN
				bNeg := 1;
				dBegin := -dBegin + 1.0; //-dBegin;
			ELSE
				bNeg := 1;
				dBegin := -dBegin;
			END_IF
		END_IF
		pnBegin^ := TRUNC(dBegin);
		IF(bNeg) THEN
			pnBegin^ := -(pnBegin^);
		END_IF

		dDiv := EXPT(10,pnBegin^);
		in := in + 5 * dDiv / 1e15;

{IF COMPILERVERSION(>=, '3.3.0.10')}
		WHILE (dDiv > 0.0 AND i < 6) DO
			nDig := DINT_TO_UDINT(TRUNC((in / dDiv) + 5e-14));
			IF (nDig > 9 AND bFirst) THEN
				nDig := 0;
			ELSIF (nDig > 9 AND NOT bFirst) THEN
				pstr[0] := 16#31;//'1';
				pstr[1] := 16#30;//'0';
				pstr[2] := 16#30;//'0';
				pstr := pstr + 3;
				pnBegin^  := pnBegin^ + 1;
				EXIT;
			END_IF

			IF (NOT bFirst AND (nDig <> 0)) THEN
				bFirst := 1;
			END_IF
			IF (bFirst AND i < 6) THEN
				pstr[0] := UDINT_TO_BYTE(nDig) + 16#30; //'0';
				pstr := pstr + 1;
				dDiff := UDINT_TO_REAL(nDig) * dDiv;
				in := in - dDiff;
				i := i+1;
			END_IF
			dDiv := dDiv / 10.0;
			nDigits := nDigits-1;
		END_WHILE
{ELSE}		
		WHILE (dDiv >= REAL#1e-40 AND i < 6) DO
			nDig := DINT_TO_UDINT(TRUNC((in / dDiv) + 5e-14));
			IF (nDig > 9 AND bFirst) THEN
				nDig := 0;
			ELSIF (nDig > 9 AND NOT bFirst) THEN
				pstr[0] := 16#31;//'1';
				pstr[1] := 16#30;//'0';
				pstr[2] := 16#30;//'0';
				pstr := pstr + 3;
				pnBegin^  := pnBegin^ + 1;
				EXIT;
			END_IF

			IF (NOT bFirst AND (nDig <> 0)) THEN
				bFirst := 1;
			END_IF
			IF (bFirst AND i < 6) THEN
				pstr[0] := UDINT_TO_BYTE(nDig) + 16#30; //'0';
				pstr := pstr + 1;
				dDiff := UDINT_TO_REAL(nDig) * dDiv;
				in := in - dDiff;
				i := i+1;
			END_IF
			dDiv := dDiv / 10.0;
			nDigits := nDigits-1;
		END_WHILE
{END_IF}

		pstr[0] := 0;
		ppstr^ := pstr;
		{implicit off}

pou.interface:
{attribute 'hide'}
// new and better way to convert single precision float values to string
{implicit on}
FUNCTION new__real32__to__string: STRING(25)(* Area: 0, Offset: 0x1760 (5984)*)
VAR_INPUT
in : REAL;(* Area: 65535, Offset: 0x0 (0)*)
dwType: DWORD;
END_VAR
VAR
index: INT;
pdw : POINTER TO DWORD;
dw : DWORD;

bSign : BOOL;
decexponent: INT;
binexponent: INT;
binmantissa: DINT;
decmantissa: DINT;
strMantissaRaw: STRING(12);
strMantissa: STRING(15);
pstrMantissa: POINTER TO BYTE;
nLen: INT;
i: INT;
bFirstChar: BOOL;
nNewExponent: INT;
nPointPosition: INT;
nIndexMantissaNew : INT;
bNan, bInf : BOOL;

Exponent : ARRAY [0..1] OF BYTE;
bNegExponent : BOOL;
nTens: BYTE;
nOnes: BYTE;

PF : POINTER TO REAL := ADR(__CONVERSION_CONSTANTS.F);

bContainsPoint : BOOL := FALSE;

END_VAR
VAR CONSTANT
CHAR_0 : BYTE := 16#30;
CHAR_POINT : BYTE := 16#2E;
CHAR_MINUS : BYTE := 16#2D;
CHAR_E : BYTE := 16#45;
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}
pdw := ADR(in);
dw := pdw^;

// special case of 0
IF dw = 0 OR dw = 16#80000000 THEN
	new__real32__to__string := '0.0';
	RETURN;
END_IF

__ExtractReal(f := in, bS => bSign, iE => binexponent, diM => binmantissa, xNan => bNan, xInf => bInf);

IF bNan THEN
	new__real32__to__string := '#NaN';
	RETURN;
END_IF

IF bInf THEN
	new__real32__to__string := '#Inf';

{IF COMPILERVERSION(>=, '3.5.5.0')}
	IF (bSign) THEN
		new__real32__to__string := '-#Inf';
	END_IF
{END_IF}

	RETURN;
END_IF

index := binexponent + 126;
decexponent := __CONVERSION_CONSTANTS.E[index];
decmantissa := REAL_TO_DINT(PF[index]*DINT_TO_REAL(binmantissa));
strMantissaRaw := DINT_TO_STRING(decmantissa);

nLen := 0;

FOR i := 0 TO 12 DO
	IF strMantissaRaw[i] = 0 THEN
		nLen := i;
		EXIT;
	END_IF
END_FOR

IF nLen > 12 THEN
	// should never happen! maximal length is 8!
	nLen := 12;
END_IF
bFirstChar := FALSE;
nNewExponent := decexponent+nLen-1;
nPointPosition := 1;

// exponents between -4 and 8 are not displayed using E10
IF (nNewExponent >= -4) AND (nNewExponent < 8) THEN
	nPointPosition := nPointPosition + nNewExponent;
	nNewExponent := 0;
END_IF

// fill result mantissa with end of string
// so we don't have to care about correct ending
{IF COMPILERVERSION(>=, '3.5.11.0')}
FOR i := 0 TO sizeof(strMantissa)-1 DO
	strMantissa[i] := 0; 
END_FOR
{ELSE}
FOR i := 0 TO 13 DO
	strMantissa[i] := 0; 
END_FOR
{END_IF}




pstrMantissa := ADR(strMantissa);

IF (bSign) THEN
	pstrMantissa[0] := CHAR_MINUS;
	pstrMantissa := pstrMantissa + 1;
END_IF

FOR i := nPointPosition-1 TO nLen-1 BY -1 DO
	bFirstChar := TRUE;
	pstrMantissa[i] := CHAR_0;	
END_FOR

nIndexMantissaNew := nLen-1;
IF nPointPosition <= 0 THEN
	nIndexMantissaNew := nIndexMantissaNew - nPointPosition + 2;
ELSIF nPointPosition <= nLen-1 THEN
	nIndexMantissaNew := nIndexMantissaNew + 1;
END_IF


FOR i := nLen-1 TO 0 BY -1 DO
	// Skip trailing zeros
	IF (nIndexMantissaNew = nPointPosition) THEN
		IF (bFirstChar) THEN
			pstrMantissa[nIndexMantissaNew] := CHAR_POINT; 
			bContainsPoint := TRUE; 
		END_IF
		nIndexMantissaNew := nIndexMantissaNew - 1;
		bFirstChar := TRUE; // no more skipping after decimal point			
	END_IF

	IF (NOT(bFirstChar) AND strMantissaRaw[i] = CHAR_0) THEN
		nIndexMantissaNew := nIndexMantissaNew - 1;	
		CONTINUE;
	END_IF
	bFirstChar := TRUE;
	pstrMantissa[nIndexMantissaNew] := strMantissaRaw[i];
	nIndexMantissaNew := nIndexMantissaNew - 1;
END_FOR

WHILE nIndexMantissaNew > 1 DO
	pstrMantissa[nIndexMantissaNew] := CHAR_0;
	nIndexMantissaNew := nIndexMantissaNew - 1;
END_WHILE
IF nIndexMantissaNew = 1 THEN
	pstrMantissa[1] := CHAR_POINT;	
	pstrMantissa[0] := CHAR_0;	
	bContainsPoint := TRUE; 
END_IF

IF nNewExponent <> 0 THEN

	IF nNewExponent < 0 THEN
		bNegExponent := TRUE;
		nNewExponent := 0 - nNewExponent;
	END_IF

	nTens := INT_TO_BYTE(nNewExponent) / 10;
	nOnes := INT_TO_BYTE(nNewExponent) MOD 10;
	FOR i := 0 TO 12 DO
		IF strMantissa[i] = 0 THEN
			strMantissa[i] := CHAR_E; 
			i := i + 1;
			IF (bNegExponent) THEN
				strMantissa[i] := CHAR_MINUS;
				i := i + 1;
			END_IF
			strMantissa[i] := CHAR_0 + nTens;
			strMantissa[i+1] := CHAR_0 + nOnes;
			strMantissa[i+2] := 0;
			EXIT;
		END_IF
	END_FOR
ELSIF NOT(bContainsPoint) THEN
	(*special code for whole numbers, some want to have trailing .0*)
	FOR i := 0 TO 12 DO
		IF strMantissa[i] = 0 THEN
			strMantissa[i] := CHAR_POINT; 
			strMantissa[i+1] := CHAR_0; 
			strMantissa[i+2] := 0;
			EXIT;
		END_IF
	END_FOR	
END_IF

new__real32__to__string := strMantissa;

		{implicit off}

pou.interface:
{attribute 'hide'}
{implicit on}
FUNCTION __ExtractReal : BOOL
VAR_INPUT
f : REAL ;    // The floating point number to extract.
END_VAR
VAR_OUTPUT
bS   : BOOL ;
iE  : INT ;        // The  exponent
diM : DINT ;       // The mantissa
xNaN : BOOL ;      // True iff f is NaN, iE and diM are 0 in this case
xInf : BOOL ;      // True iff f is infinity, diM = 1 for +Infinity and -1 for -Infinity, iE is 0
END_VAR
VAR
uiE  : UINT ;
udiM : UDINT ;
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}
xNaN := FALSE ;
xInf := FALSE ;

__ExtractRealRaw(f:=f, bs=>bs, uiE=>uiE, udiM=>udiM) ;
IF uiE = 0 THEN
 IF udiM = 0 THEN // zero
  iE  := 0 ;
  diM := 0 ;
 ELSE // subnormal
  iE  := 1-(__CONVERSION_CONSTANTS.EXP_BIAS_REAL(*+__CONVERSION_CONSTANTS.EXP_OFFSET_REAL*)) ;
  diM := UDINT_TO_DINT(udiM) ;
 END_IF
ELSIF uiE = __CONVERSION_CONSTANTS.RES_EXP_REAL THEN // NaN or Infinity
 iE := 0 ;
 IF udiM = 0 THEN
  diM  := SEL(bS, 1, -1) ;
  xInf := TRUE ;
 ELSE
  diM  := 0 ;
  xNaN := TRUE ;
 END_IF
ELSE
 iE  := UINT_TO_INT(uiE) - (__CONVERSION_CONSTANTS.EXP_BIAS_REAL (*+ __CONVERSION_CONSTANTS.EXP_OFFSET_REAL*)) ;
 diM := UDINT_TO_DINT(udiM OR SHL(UDINT#1,__CONVERSION_CONSTANTS.EXP_OFFSET_REAL)) ;
END_IF

		{implicit off}

pou.interface:
{attribute 'hide'}
{implicit on}
/// Extracts the components of a REAL floating point number without
/// interpreting them.
/// Extracts the sign, (biased) exponent, and mantissa of a REAL value.
/// We assume the IEEE 754 binary32 format.
/// All values, including NaN and Infinity are supported.
/// See http://en.wikipedia.org/wiki/Single_precision_floating-point_format
FUNCTION __ExtractRealRaw : BOOL
VAR_INPUT
f : REAL ;    // The floating point number to extract.
END_VAR
VAR_OUTPUT
bS   : BOOL ;  // The sign bit
uiE  : UINT ;  // The (biased) exponent
udiM : UDINT ; // The mantissa as stored in the REAL, without the leading bit 24 set
END_VAR
VAR
pudi : POINTER TO UDINT ;
udi : UDINT ;
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
pudi := ADR(f) ;
udi  := pudi^ ;
bS   := SHR(udi, 31) <> 0 ;
uiE  := UDINT_TO_UINT(SHR(udi AND __CONVERSION_CONSTANTS.EXP_MASK_REAL, __CONVERSION_CONSTANTS.EXP_OFFSET_REAL)) ;
udiM := udi AND __CONVERSION_CONSTANTS.MANT_MASK_REAL ;
		{noflow}
		{implicit off}

pou.interface:
{implicit on}
FUNCTION real32__to__string : STRING(255)
VAR_INPUT
	in: REAL;		
	dwType: DWORD;
END_VAR
VAR
	sz : STRING;
	pszHelp : POINTER TO BYTE;
	pszSource : POINTER TO BYTE;
	pszHelpSource : POINTER TO BYTE;
	pszDest : POINTER TO BYTE;
	nSign : DINT := 1;
	i : DINT;
	iExp10 : DINT;
	nExpSign : DINT := 1;
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}
		pszDest := ADR(real32__to__string);
		pszHelp := ADR(sz);

		// If dwType REAL just use first 6 Numbers
		IF (dwType = __TypeClass.TYPE_REAL) THEN
			IF (in < 0) THEN
				i := TRUNC(LOG(-in));
			ELSIF (in >0) THEN
				i := TRUNC(LOG(in));
			ELSE
				i := 0;
			END_IF      
      {IF COMPILERVERSION(>=, '3.4.4.0')}
			  IF (in >= 0) THEN
				  in := in * TRUNC(EXPT(10,6-i)) + 0.5;
			  ELSE
				  in := in * TRUNC(EXPT(10,6-i)) - 0.5;
			  END_IF			
			 {IF COMPILERVERSION(>=, '3.4.5.70')}	 
					IF (i > 6) THEN
						in := DINT_TO_REAL(TRUNC(in)) / EXPT(10,6-i);
					ELSE
						in := DINT_TO_REAL(TRUNC(in)) / TRUNC(EXPT(10,6-i));
					END_IF      
				{ELSE}      
  					in := DINT_TO_REAL(TRUNC(in)) / TRUNC(EXPT(10,6-i));      
				{END_IF}
      {ELSE}      
			  IF (in >= 0) THEN
				  in := in * EXPT(10,6-i) + 0.5;
			  ELSE
				  in := in * EXPT(10,6-i) - 0.5;
			  END_IF
			  in := DINT_TO_REAL(TRUNC(in)) / EXPT(10,6-i);
      {END_IF}      
			i := 0;
		END_IF
		// Emit sign
		IF (in < 0) THEN
			pszDest[0] := BYTE#16#2d;
			pszDest := pszDest + 1;
			nSign := -1;
		END_IF	
		IF (in = 0) THEN
			pszDest[0] := 16#30; //'0';
			pszDest[1] := 16#2e;//'.';
			pszDest[2] := 16#30;
			pszDest[3] := 0;//'\0';
		ELSE
			__HelpReal32Convert(DINT_TO_REAL(nSign) * in,ADR(pszHelp),ADR(iExp10));
			pszSource := ADR(sz);
			IF(iExp10 >= 0 AND iExp10 < 14) THEN
				FOR(i := 0) TO iExp10 DO
					pszDest[i] := pszSource[i];
				END_FOR
				pszDest[i] := 16#2e;//'.';
				pszDest := pszDest + i + 1;
				pszSource := pszSource + i;
				WHILE (pszSource[0] <> 0) DO
					pszDest[0] := pszSource[0];
					pszDest := pszDest + 1;
					pszSource := pszSource + 1;
					IF(pszSource[0] = 16#30) THEN //'0'
						pszHelpSource := pszSource;
						WHILE (pszHelpSource[0] = 16#30) DO
							pszHelpSource := pszHelpSource + 1;
						END_WHILE
						IF (pszHelpSource[0] = 0) THEN
							EXIT;
						END_IF
					END_IF
				END_WHILE
				pszDest[0] := 0;//'\0';
			ELSIF (iExp10 >= 14 OR iExp10 <0) THEN
				pszDest[0] := pszSource[0];
				pszDest[1] := 16#2e;//'.';
				pszDest := pszDest + 2;
				pszSource := pszSource + 1;
				WHILE (pszSource[0] <> 0) DO
					pszDest[0] := pszSource[0];
					pszDest := pszDest + 1;
					pszSource := pszSource + 1;
					IF(pszSource[0] = 16#30) THEN //'0'
						pszHelpSource := pszSource;
						WHILE (pszHelpSource[0] = 16#30) DO
							pszHelpSource := pszHelpSource+1;
						END_WHILE
						IF (pszHelpSource[0] = 0) THEN
							EXIT;
						END_IF
					END_IF
				END_WHILE
				pszDest[0] := 16#65; //'e';
				pszDest := pszDest + 1;
				IF (iExp10 < 0) THEN
					pszDest[0] := BYTE#16#2d;
					pszDest := pszDest + 1;
					nExpSign := -1;
				END_IF
				__HelpConvert(DINT_TO_UDINT((nExpSign) * iExp10),ADR(pszDest),1);
				pszDest[0] := 0;
			END_IF
		END_IF
		{implicit off}

pou.interface:
{implicit on}
FUNCTION string__to__real32 : REAL
VAR_INPUT
in: STRING(255);
END_VAR
VAR
d : REAL := 1;
dRealVal : REAL := 0;
iExp : DINT := 0;
nSign : DINT := 1;
pstr : POINTER TO BYTE := ADR(in);
iSign: INT;
{IF COMPILERVERSION(>=, '3.5.5.0')}
pdwHelp : POINTER TO DWORD := ADR(string__to__real32);
{END_IF}

END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}
		__SkipWhiteSpace(ADR(pstr));

		IF (pstr[0] = BYTE#16#2d) (*'-'*) THEN
			nSign := -1;
			pstr := pstr+1;
		ELSIF (pstr[0] = 16#2b (*'+'*)) THEN
			pstr := pstr+1;
		END_IF

{IF COMPILERVERSION(>=, '3.5.5.0')}
IF pstr[0] =  16#23 (*''#*)THEN
	IF pstr[1] = 16#4E (*N*)
		AND pstr[2] = 16#61 (*a*)
		AND pstr[3] = 16#4E (*N*)
	THEN
		pdwHelp^ := __CONVERSION_CONSTANTS.NAN_REAL;
		RETURN;
	END_IF
	IF pstr[1] = 16#49 (*I*)
		AND pstr[2] = 16#6E (*n*)
		AND pstr[3] = 16#66 (*f*)
	THEN
		IF nSign = -1 THEN
			pdwHelp^ := __CONVERSION_CONSTANTS.NINF_REAL;
		ELSE
			pdwHelp^ := __CONVERSION_CONSTANTS.PINF_REAL;
		END_IF
		RETURN;
	END_IF
END_IF
{END_IF}

		WHILE ((pstr[0] >= 16#30 (*'0'*) AND pstr[0] <= 16#39 (*'9'*)) OR pstr[0] = 16#5f (*'_'*))
		DO
			IF (pstr[0] <> 16#5f) THEN
				dRealVal := dRealVal * 10 + pstr[0] - 16#30;
			END_IF
			pstr := pstr+1;
		END_WHILE

		IF (pstr[0] = 16#2e (*'.'*)) THEN
			pstr := pstr+1;
			WHILE ((pstr[0] >= 16#30 (*'0'*) AND pstr[0] <= 16#39 (*'9'*)) OR pstr[0] = 16#5f (*'_'*))
			DO 
				IF (pstr[0] <> 16#5f) THEN
					d := d / 10.0;
					dRealVal := dRealVal + (pstr[0] - 16#30) * d;
				END_IF
				pstr := pstr+1;
			END_WHILE
		END_IF

		IF (pstr[0] = 16#65 (*'e'*) OR pstr[0] = 16#45 (*'E'*)) THEN
			iSign := 1;
			pstr := pstr+1;
			IF (pstr[0] = 16#2d(*'-'*)) THEN
				iSign := -1;
				pstr := pstr+1;
			ELSIF (pstr[0] = 16#2b (*'+'*)) THEN
				pstr := pstr+1;
			END_IF

			WHILE ((pstr[0] >= 16#30 (*'0'*) AND pstr[0] <= 16#39 (*'9'*)) OR pstr[0] = 16#5f (*'_'*))
			DO
				IF (pstr[0] <> 16#5f) THEN
					iExp := iExp * 10 + pstr[0] - 16#30;
				END_IF
				pstr := pstr+1;
			END_WHILE
			dRealVal := dRealVal * EXPT(10.0, iExp * iSign);
		END_IF
		string__to__real32 := DINT_TO_REAL(nSign) * dRealVal;
		{implicit off}

data-type.interface:
/// A structure representing the version information of a software or firmware component. 
TYPE VERSION :
STRUCT
/// The major version number. This is typically incremented for significant releases that may include major new features or changes.
uiMajor : UINT;
/// The minor version number. This is incremented for releases that add smaller features or improvements and may include significant fixes.
uiMinor : UINT;
/// The service pack number. This is used to indicate updates that usually include bug fixes, performance improvements, and minor feature enhancements.
uiServicePack : UINT;
/// The patch number. This is incremented for very small changes or bug fixes that do not significantly alter the functionality.
uiPatch : UINT;
END_STRUCT
END_TYPE
